import unittest
from candidate import strlen

class TestStrlen(unittest.TestCase):
    def test_strlen_empty_string(self):
        self.assertEqual(strlen(''), 0)

    def test_strlen_normal_string(self):
        self.assertEqual(strlen('abc'), 3)

    def test_strlen_string_with_spaces(self):
        self.assertEqual(strlen('hello world'), 11)

    def test_strlen_string_with_special_chars(self):
        self.assertEqual(strlen('!@#$%'), 5)

    def test_strlen_unicode_string(self):
        self.assertEqual(strlen('café'), 4)

    def test_strlen_none_raises_type_error(self):
        with self.assertRaises(TypeError):
            strlen(None)

    def test_strlen_integer_raises_type_error(self):
        with self.assertRaises(TypeError):
            strlen(5)

    def test_strlen_whitespace_only_string(self):
        self.assertEqual(strlen('   '), 3)

    def test_strlen_long_string(self):
        self.assertEqual(strlen('a' * 1000), 1000)
